CREATE TABLE business_assets(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),original_mime TEXT NOT NULL,original_key TEXT NOT NULL,preview_key TEXT NOT NULL,sha256 TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE inventory_receipts(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,vendor TEXT NOT NULL,reference TEXT NOT NULL,data TEXT NOT NULL,original_mime TEXT NOT NULL,original_key TEXT NOT NULL,preview_key TEXT NOT NULL,sha256 TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(business_id,idempotency_key),UNIQUE(business_id,sha256));
